/// Determines whether the supplied string is a valid ISBN number
pub fn is_valid_isbn(isbn: &str) -> bool {
    // Clean the ISBN by removing hyphens
    let cleaned: Vec<char> = isbn.chars().filter(|&c| c != '-').collect();

    // Must have exactly 10 characters
    if cleaned.len() != 10 {
        return false;
    }

    let mut sum = 0;
    let mut weight = 10;

    for (i, c) in cleaned.iter().enumerate() {
        let value = match c {
            '0'..='9' => c.to_digit(10).unwrap() as i32,
            'X' if i == 9 => 10, // X is only valid as last character
            _ => return false,
        };

        sum += value * weight;
        weight -= 1;
    }

    sum % 11 == 0
}
>>>>>>> REPLACE
```

This implementation:
1. Removes all hyphens from the input
2. Validates the cleaned ISBN has exactly 10 characters
3. Checks each character:
   - First 9 must be digits (0-9)
   - Last character can be digit or X (which counts as 10)
4. Calculates the weighted sum according to ISBN-10 formula
5. Checks if the sum is divisible by 11

The code handles:
- Hyphenated ISBNs (like "3-598-21508-8")
- X check character (like "3-598-21507-X")
- Invalid characters and incorrect lengths
- Proper position requirements for X (only allowed as last character)

