import asyncio
import unittest
from types import SimpleNamespace

from minagent.environment import DockerEnvironment

# Dummy ExecResult class
class DummyExecResult:
    def __init__(self, stdout=""):
        self.stdout = stdout

# Dummy docker_compose function to simulate docker compose commands
async def dummy_docker_compose(cmd, timeout=None):
    if "build" in cmd:
        return DummyExecResult(stdout="image built")
    elif "up" in cmd:
        return DummyExecResult(stdout="containers started")
    elif "down" in cmd:
        return DummyExecResult(stdout="containers stopped")
    elif "ps" in cmd:
        # Simulate two container names
        return DummyExecResult(stdout="container1\ncontainer2")
    return DummyExecResult(stdout="")


class TestDockerEnvironment(unittest.IsolatedAsyncioTestCase):
    async def asyncSetUp(self):
        self.env = DockerEnvironment(compose_file="dummy-compose.yml")
        # Patch the docker_compose function in the environment module
        import minagent.environment as env_mod
        env_mod.docker_compose = dummy_docker_compose

    async def test_build_image(self):
        result = await self.env.build_image()
        self.assertEqual(result.stdout, "image built")

    async def test_start_agent_containers(self):
        result = await self.env.start_agent_containers(count=2)
        self.assertEqual(result.stdout, "containers started")

    async def test_stop_agent_containers(self):
        result = await self.env.stop_agent_containers()
        self.assertEqual(result.stdout, "containers stopped")

    async def test_get_container_names(self):
        names = await self.env.get_container_names()
        self.assertEqual(names, ["container1", "container2"])

if __name__ == '__main__':
    unittest.main()

