news_url = 'https://cryptonews-api.com/api/v1/category'
news_params = {
    'section': 'general',
    'items': 7,
    'token': 'YOUR_API_KEY'  # Replace with your actual API key
}
news_response = requests.get(news_url, params=news_params)
news_data = news_response.json()

# Combine price and news data
for i, coin in enumerate(coins):
    if i < len(news_data['data']):
        coin['news'] = news_data['data'][i]['title']
    else:
        coin['news'] = 'No news available'

return jsonify(coins)

